begin;
create extension if not exists pgcrypto;
create type public.org_role as enum ('org_owner','case_manager','case_officer','independent_reviewer','auditor_readonly');
create type public.case_status as enum ('new','acknowledged','triage','investigating','awaiting_reporter','resolved','closed','archived');
create type public.case_priority as enum ('low','normal','high','urgent');

create table public.organizations (id uuid primary key default gen_random_uuid(), slug text not null unique check(slug~'^[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])?$'), name text not null check(length(name) between 2 and 160), sector text, verified_at timestamptz, intake_enabled boolean not null default false, onboarding_state text not null default 'draft', privacy_contact text, controller_notice_version text, retention_days int not null default 365 check(retention_days between 1 and 3650), deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organization_members (organization_id uuid not null references public.organizations on delete cascade, user_id uuid not null references auth.users on delete cascade, role public.org_role not null, active boolean not null default true, mfa_required boolean not null default true, invited_by uuid references auth.users, joined_at timestamptz not null default now(), primary key(organization_id,user_id));
create table public.organization_verifications (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, verification_type text not null, status text not null check(status in('pending','approved','rejected','expired')), reviewed_at timestamptz, proof_reference text, created_at timestamptz not null default now());
create table public.case_categories (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, label text not null check(length(label) between 2 and 80), enabled boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,label));
create table public.cases (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, public_reference text not null unique check(public_reference~'^WZ-[0-9]{4}-[A-F0-9]{24}$'), category_id uuid not null references public.case_categories, status public.case_status not null default 'new', priority public.case_priority not null default 'normal', assigned_member_id uuid, encrypted_title jsonb not null, encrypted_body jsonb not null, encryption_metadata jsonb not null default '{"version":1}', submitted_at timestamptz not null default now(), closed_at timestamptz, hold_flag boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(organization_id,assigned_member_id) references public.organization_members(organization_id,user_id));
create index cases_org_status_date on public.cases(organization_id,status,submitted_at desc);
create table public.case_access_credentials (case_id uuid primary key references public.cases on delete cascade, verifier_hmac text not null, pepper_version int not null default 1, rotated_at timestamptz, failed_attempt_count int not null default 0, lockout_until timestamptz, created_at timestamptz not null default now());
create table public.case_messages (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, case_id uuid not null references public.cases on delete cascade, sender_kind text not null check(sender_kind in('reporter','officer')), sender_member_id uuid references auth.users, encrypted_body jsonb not null, encryption_metadata jsonb not null default '{"version":1}', created_at timestamptz not null default now(), deleted_at timestamptz);
create index messages_case_date on public.case_messages(organization_id,case_id,created_at);
create table public.case_notes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, case_id uuid not null references public.cases on delete cascade, author_id uuid not null references auth.users, encrypted_body jsonb not null, encryption_metadata jsonb not null default '{"version":1}', created_at timestamptz not null default now());
create table public.case_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, case_id uuid not null references public.cases on delete cascade, event_type text not null, actor_id uuid references auth.users, safe_metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.case_access_grants (organization_id uuid not null references public.organizations on delete cascade, case_id uuid not null references public.cases on delete cascade, member_id uuid not null references auth.users on delete cascade, grant_type text not null check(grant_type in('standard','restricted','review')), granted_by uuid not null references auth.users, revoked_at timestamptz, conflict_reason_code text, created_at timestamptz not null default now(), primary key(case_id,member_id));
create table public.attachments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, case_id uuid not null references public.cases on delete cascade, message_id uuid references public.case_messages on delete cascade, storage_key text not null unique, filename_display_sanitized text not null, media_type text not null check(media_type in('application/pdf','image/png','image/jpeg','text/plain')), bytes int not null check(bytes between 1 and 5242880), sha256 text not null, scan_status text not null default 'quarantined' check(scan_status in('quarantined','clean','rejected','error')), encrypted_file_key_metadata jsonb, created_at timestamptz not null default now(), deleted_at timestamptz);
create table public.audit_events (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations on delete cascade, actor_pseudonym text, action text not null, target_kind text not null, target_id uuid, success boolean not null, safe_metadata jsonb not null default '{}', created_at timestamptz not null default now(), integrity_mac text not null, previous_mac text);
create table public.retention_jobs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, case_id uuid not null references public.cases on delete cascade, due_at timestamptz not null, status text not null default 'pending' check(status in('pending','held','complete','failed')), hold_reason_code text, completed_at timestamptz, created_at timestamptz not null default now(), unique(case_id));
create table public.legal_document_versions (id uuid primary key default gen_random_uuid(), doc_type text not null, version text not null, effective_at timestamptz not null, content_sha256 text not null, published_at timestamptz, created_at timestamptz not null default now(), unique(doc_type,version));
create table public.organization_acceptances (organization_id uuid not null references public.organizations on delete cascade, member_id uuid not null references auth.users, document_version_id uuid not null references public.legal_document_versions, accepted_at timestamptz not null default now(), primary key(organization_id,member_id,document_version_id));
create table public.submission_limits (rate_key text not null, scope text not null, bucket_start timestamptz not null, count int not null default 1, expires_at timestamptz not null, primary key(rate_key,scope,bucket_start));
create table public.submission_tokens (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, token_hmac text not null unique, expires_at timestamptz not null, used_at timestamptz, created_at timestamptz not null default now());
create function public.consume_submission_limit(p_rate_key text,p_scope text,p_limit int) returns boolean language plpgsql security definer set search_path='' as $$ declare v_count int; v_bucket timestamptz:=date_trunc('hour',now()); begin insert into public.submission_limits(rate_key,scope,bucket_start,count,expires_at) values(p_rate_key,p_scope,v_bucket,1,v_bucket+interval '25 hours') on conflict(rate_key,scope,bucket_start) do update set count=public.submission_limits.count+1 returning count into v_count; delete from public.submission_limits where expires_at<now(); return v_count<=p_limit; end $$;
revoke all on function public.consume_submission_limit(text,text,int) from public;
grant execute on function public.consume_submission_limit(text,text,int) to service_role;

create function public.has_case_access(p_case uuid,p_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.case_access_grants g join public.organization_members m on m.organization_id=g.organization_id and m.user_id=g.member_id where g.case_id=p_case and g.organization_id=p_org and g.member_id=(select auth.uid()) and g.revoked_at is null and m.active and (not exists(select 1 from public.case_access_grants restricted where restricted.case_id=p_case and restricted.organization_id=p_org and restricted.grant_type='restricted' and restricted.revoked_at is null) or m.role='independent_reviewer')) $$;
revoke all on function public.has_case_access(uuid,uuid) from public; grant execute on function public.has_case_access(uuid,uuid) to authenticated;

alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.organization_verifications enable row level security; alter table public.case_categories enable row level security; alter table public.cases enable row level security; alter table public.case_access_credentials enable row level security; alter table public.case_messages enable row level security; alter table public.case_notes enable row level security; alter table public.case_events enable row level security; alter table public.case_access_grants enable row level security; alter table public.attachments enable row level security; alter table public.audit_events enable row level security; alter table public.retention_jobs enable row level security; alter table public.legal_document_versions enable row level security; alter table public.organization_acceptances enable row level security; alter table public.submission_limits enable row level security; alter table public.submission_tokens enable row level security;
create policy "verified public organization" on public.organizations for select to anon using(verified_at is not null and deleted_at is null);
create policy "public enabled categories" on public.case_categories for select to anon using(enabled and exists(select 1 from public.organizations o where o.id=organization_id and o.verified_at is not null and o.deleted_at is null));
create policy "members see own membership" on public.organization_members for select to authenticated using(user_id=(select auth.uid()));
create policy "members see organization" on public.organizations for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=id and m.user_id=(select auth.uid()) and m.active));
create policy "granted case read" on public.cases for select to authenticated using(public.has_case_access(id,organization_id));
create policy "granted messages read" on public.case_messages for select to authenticated using(public.has_case_access(case_id,organization_id));
create policy "granted notes read" on public.case_notes for select to authenticated using(public.has_case_access(case_id,organization_id));
create policy "granted events read" on public.case_events for select to authenticated using(public.has_case_access(case_id,organization_id));
create policy "own grants read" on public.case_access_grants for select to authenticated using(member_id=(select auth.uid()));
create policy "org audit read" on public.audit_events for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=audit_events.organization_id and m.user_id=(select auth.uid()) and m.active and m.role in('org_owner','case_manager','independent_reviewer','auditor_readonly')));

create function public.submit_report(p_token_id uuid,p_org_id uuid,p_category_id uuid,p_reference text,p_encrypted_title jsonb,p_encrypted_body jsonb,p_verifier_hmac text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_case uuid; begin update public.submission_tokens set used_at=now() where id=p_token_id and organization_id=p_org_id and used_at is null and expires_at>now(); if not found then raise exception 'invalid token'; end if; if not exists(select 1 from public.organizations where id=p_org_id and verified_at is not null and intake_enabled and deleted_at is null) or not exists(select 1 from public.case_categories where id=p_category_id and organization_id=p_org_id and enabled) then raise exception 'channel unavailable'; end if; insert into public.cases(organization_id,public_reference,category_id,encrypted_title,encrypted_body) values(p_org_id,p_reference,p_category_id,p_encrypted_title,p_encrypted_body) returning id into v_case; insert into public.case_access_credentials(case_id,verifier_hmac) values(v_case,p_verifier_hmac); insert into public.case_events(organization_id,case_id,event_type,safe_metadata) values(p_org_id,v_case,'submitted','{}'); insert into public.retention_jobs(organization_id,case_id,due_at) select p_org_id,v_case,now()+(retention_days||' days')::interval from public.organizations where id=p_org_id; return v_case; end $$;
revoke all on function public.submit_report(uuid,uuid,uuid,text,jsonb,jsonb,text) from public;
grant execute on function public.submit_report(uuid,uuid,uuid,text,jsonb,jsonb,text) to service_role;
create function public.record_failed_recovery(p_case_id uuid) returns void language plpgsql security definer set search_path='' as $$ update public.case_access_credentials set failed_attempt_count=failed_attempt_count+1,lockout_until=case when failed_attempt_count+1>=10 then now()+interval '15 minutes' else lockout_until end where case_id=p_case_id $$;
revoke all on function public.record_failed_recovery(uuid) from public;
grant execute on function public.record_failed_recovery(uuid) to service_role;

revoke all on all tables in schema public from anon,authenticated;
grant select on public.organizations,public.case_categories to anon;
grant select on public.organizations,public.organization_members,public.cases,public.case_messages,public.case_notes,public.case_events,public.case_access_grants,public.audit_events to authenticated;
revoke update,delete on public.audit_events from anon,authenticated;
commit;
